/* The hymn index (/hymns, generated by tools/blog/build.mjs): a filter box over the list. Every hymn
 * carries its titles, first line, tune, writers, season and topics in data-search; typing hides the
 * hymns that do not match every word, and the season buttons fill the box. The list itself is plain
 * HTML and works without this. A ?q= in the address fills the box on arrival. Plain script, no build step. */
(function () {
  "use strict";
  var box = document.getElementById("hymn-find"), input = document.getElementById("hymn-filter");
  if (!box || !input) return;
  var items = Array.prototype.slice.call(document.querySelectorAll(".hymn-item[data-search]"));
  var sections = Array.prototype.slice.call(document.querySelectorAll(".hymn-letter"));
  var count = document.getElementById("hymn-count"), none = document.getElementById("hymn-none");
  var nav = document.querySelector(".az");
  box.hidden = false;

  function words(s) {
    var t = String(s || "").toLowerCase();
    if (t.normalize) t = t.normalize("NFKD").replace(/[̀-ͯ]/g, "");
    return t.replace(/[^a-z0-9]+/g, " ").trim().split(" ").filter(Boolean);
  }
  function apply() {
    var q = words(input.value), shown = 0;
    items.forEach(function (li) {
      var hay = " " + li.getAttribute("data-search") + " ";
      var ok = q.every(function (w) { return hay.indexOf(" " + w) >= 0; });
      li.hidden = !ok;
      if (ok) shown++;
    });
    sections.forEach(function (s) { s.hidden = !s.querySelector(".hymn-item:not([hidden])"); });
    if (nav) nav.hidden = q.length > 0;
    count.textContent = q.length ? shown + (shown === 1 ? " hymn" : " hymns") + " found" : "";
    none.hidden = shown > 0;
  }
  input.addEventListener("input", apply);
  Array.prototype.forEach.call(box.querySelectorAll("[data-filter]"), function (b) {
    b.addEventListener("click", function () {
      input.value = input.value === b.getAttribute("data-filter") ? "" : b.getAttribute("data-filter");
      apply();
      if (window.nfTrack) try { window.nfTrack("Hymn filter: " + b.textContent); } catch (e) { /* ignore */ }
    });
  });
  try {
    var q = new URLSearchParams(window.location.search).get("q");
    if (q) { input.value = q; apply(); }
  } catch (e) { /* an old browser: the box still works */ }
})();
